class Widget {
private:
    int id_ = 0;
    double scale;

public:
    // Default constructor
    Widget() = default;

    // Explicit custom constructor
    explicit Widget(int i) : id_(i), scale(1.0) {}

    // Destructor definition (required if virtual, or complex resources)
    ~Widget() = default;

    // Const accessor method
    int get_id() const { return id_; }

    // Rule of Five control: Disable copying
    Widget(const Widget&) = delete;
    Widget& operator=(const Widget&) = delete;
};
